/* Token Launch Radar v2.4 — one palette, one spacing scale, no framework. */
:root {
  --ink: #0e1420;
  --panel: #16202e;
  --panel2: #1c2a3c;
  --line: #2a3a4f;
  --text: #e8edf3;
  --muted: #93a1b3;
  --accent: #f2a33c;
  --accent-ink: #1a1206;
  --good: #5fd68a;
  --bad: #f27d7d;
  --radius: 10px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font: 15px/1.55 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.top {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 28px 32px 18px;
  border-bottom: 1px solid var(--line);
}
h1 { margin: 0 0 6px; font-size: 30px; letter-spacing: -0.5px; }
.sub { margin: 0; color: var(--muted); max-width: 720px; }
.meta { text-align: right; color: var(--muted); font-size: 13px; white-space: nowrap; }
.meta b { color: var(--text); font-size: 22px; display: block; }
.strip {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 14px 32px;
  border-bottom: 1px solid var(--line);
}
.chip {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 12px;
  font-size: 13px;
  color: var(--muted);
}
.chip b { color: var(--text); }
.chip .up { color: var(--good); }
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  padding: 16px 32px;
}
.controls input[type="search"], .controls select {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
  font: inherit;
}
.controls input[type="search"] { min-width: 220px; }
.check { color: var(--muted); font-size: 14px; display: flex; gap: 6px; align-items: center; }
.view {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 14px;
  font: inherit;
  cursor: pointer;
}
.view.on { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 700; }
main { padding: 0 32px 32px; }
main.detail-first { display: flex; flex-direction: column; }
main.detail-first #detail { order: -1; }
.count { color: var(--muted); margin: 4px 0 10px; }
table { width: 100%; border-collapse: collapse; background: var(--panel); border-radius: var(--radius); overflow: hidden; }
th, td { padding: 9px 12px; text-align: left; border-bottom: 1px solid var(--line); }
th { background: var(--panel2); color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.4px; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--panel2); }
tbody tr.sel { background: #2a2113; outline: 2px solid var(--accent); outline-offset: -2px; }
td .slug { color: var(--muted); font-size: 12px; }
td .val { font-weight: 700; color: var(--accent); }
.pos { color: var(--good); }
.neg { color: var(--bad); }
.hint { color: var(--muted); font-size: 13px; }
.detail {
  margin: 22px 0;
  background: var(--panel);
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  padding: 20px 22px;
}
.detail h2 { margin: 0 0 4px; font-size: 22px; }
.detail .dsub { color: var(--muted); margin: 0 0 14px; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 14px; }
.cell { background: var(--panel2); border-radius: 8px; padding: 10px 12px; }
.cell span { display: block; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.4px; }
.cell b { font-size: 17px; font-variant-numeric: tabular-nums; }
.detail h3 { margin: 16px 0 8px; font-size: 15px; }
.net {
  background: #2a2113;
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 10px 14px;
  font-weight: 700;
  color: var(--accent);
  margin: 0 0 6px;
}
.detail ol { margin: 0; padding-left: 22px; }
.detail li { margin-bottom: 8px; }
.detail li b { color: var(--accent); }
.method { margin-top: 28px; }
.method h2 { font-size: 19px; margin: 22px 0 8px; }
.method p { color: #c6d0dd; max-width: 900px; }
.method table { margin-top: 10px; }
.method tbody tr { cursor: default; }
.method tbody tr:hover { background: var(--panel); }
footer { border-top: 1px solid var(--line); padding: 16px 32px 28px; color: var(--muted); font-size: 13px; }
@media (max-width: 900px) {
  .top, .strip, .controls, main { padding-left: 16px; padding-right: 16px; }
  .top { flex-direction: column; }
  .meta { text-align: left; }
  th:nth-child(4), td:nth-child(4) { display: none; }
}
